using NeonSidekick.App;

namespace NeonSidekick.Help;

/// <summary>
/// What each settings row does, in a sentence or a few (2026-10-02, the user's call: the descriptions live in code, not in an
/// embedded README), for <c>neon_help</c> (<see cref="NeonHelp"/>). Seeded from README's "What it does" columns; a new
/// <see cref="SettingsField"/> needs its line here as it needs its README row (<c>NeonHelpCatalogTests</c> fails on a field
/// without one). Where the row lives and its default are worked out from the menus' own lists (<see cref="HelpLocation"/>),
/// never written here.
/// </summary>
public static class HelpSettings
{
    /// <summary>The row's purpose, plain text (backticks and <c>*Setting*</c> names kept).</summary>
    public static string Describe(SettingsField field) => field switch
    {
        SettingsField.Profile => "Switches to another profile (each has its own settings, persona, memory, skills and sessions).",
        SettingsField.UserLineStyle => "How the transcript draws your sent line: `quiet` (the › in the user colour, your words in the body's), `slab` (your line on a faint fill) or `bold` (the whole line bold in the user colour).",
        SettingsField.MemoryMode => "What the model may do with long-term memory: `read-write` (offered `save_memory` and `recall_memory`, every conversation opening with what it remembers), `read-only` (`recall_memory` alone: it reads, never saves; your `/remember` still saves) or `disabled` (no memory at all, `/remember` refused). `/memory read-write` / `read-only` / `disabled` (`on` / `off` too) and the buttons on `/memory`'s pane set it.",
        SettingsField.LlmUrl => "The server's OpenAI-compatible base URL (`http://127.0.0.1:1234/v1`), `embedded` for the app's own embedded LLM (see *Embedded*), or `docker:<container>` for a chosen Docker container (see *Docker servers*). `/server` fills it in. When empty, the app scans as *LLM server scan mode* says and, at startup, lets you pick a server, model and reasoning level, and saves all three. ESC at that picker takes the first server without saving it.",
        SettingsField.LlmModel => "The model id. Empty takes the first model the server lists; a Docker server serving one model saves its id here when it connects; `/model` picks one.",
        SettingsField.LlmApiKey => "The bearer token the server expects; leave it empty for local servers that need no key. A real key is saved encrypted for your Windows account (DPAPI, Windows' built-in data protection) and shown as `(set, encrypted)`. Typing a new value replaces it (`empty` stays as it is).",
        SettingsField.LlmReasoning => "How hard the model thinks, sent with every request: `none` (thinking off), `low`, `medium`, `high` or `xhigh`. `/reasoning` opens the same list.",
        SettingsField.LlmRequestTimeoutSeconds => "The longest one HTTP request may take (up to 3600).",
        SettingsField.LlmTurnTimeoutSeconds => "The longest one whole turn may take, every tool round trip included (up to 21600).",
        SettingsField.TtsOutput => "Reads replies aloud (`/tts`). Fenced code blocks and tables are shown but never read aloud, not even by `/speak`.",
        SettingsField.TtsHttpUrl => "The Kokoro-FastAPI base URL (`http://localhost:8880/v1` for a server on this machine), used while *TTS source* is `http`; empty until you set one.",
        SettingsField.TtsVoicePreset => "Sets *TTS voice*, *TTS voice 2*, *TTS voice mix* and *TTS speed* in one go. The preset itself is not saved: the row shows the preset those four match, or `(custom)`. Built in: `amanda`, `neon`, `richard`, `hunter`, `larry`, `jack`, `willow`. Your own presets go in the `voices` folder of the home, one JSON file each, and a file named like a built-in replaces it. Forty-one more come with the repo, with samples to listen to. See Voice presets.",
        SettingsField.TtsVoice => "The Kokoro voice.",
        SettingsField.TtsVoice2 => "A second voice blended in; `(none)` for the primary voice alone.",
        SettingsField.TtsVoiceMix => "The primary voice's share of the blend, 0–100 %.",
        SettingsField.TtsSpeed => "How fast the voice speaks, as a multiplier, 0.5–2.0.",
        SettingsField.SttInput => "Turns the microphone on: the push-to-talk key records a spoken message (`/stt`).",
        SettingsField.SttWake => "Saying the wake phrase at the idle line starts listening, with no key (`/wake`).",
        SettingsField.SttWakePhrase => "One to three words. It is also the interrupt phrase.",
        SettingsField.SttInterrupt => "Saying the wake phrase while a reply is being spoken cuts it short and listens (`/interrupt`).",
        SettingsField.SttInterruptEchoGuard => "Stops the assistant's own voice from triggering an interrupt: text it just spoke is ignored as an echo when it is at least this close to the wake phrase, 50–100 % (100 = the exact phrase only).",
        SettingsField.SttInterruptConfirmMs => "How long the phrase must keep showing in the recogniser's early (interim) results before it counts, 0–2000 ms.",
        SettingsField.SttPushToTalkKey => "The key that records: `F1`–`F8`, `Insert`, `Home`, `End`, `PageUp` or `PageDown`.",
        SettingsField.SttWhisperModel => "The Whisper model that turns speech into text: `ggml-tiny.en.bin`, `ggml-base.en.bin` or `ggml-small.en.bin` (downloaded on first use).",
        SettingsField.WorkingDirectory => "The folder the file and GitLib tools work in. Empty means the profile's own `files\\` folder. Editing the row opens the `/cwd browse` folder picker, and `/cwd <path>` sets a typed path.",
        SettingsField.CopyUserPrompt => "`/copy` includes your prompt above the reply. When off, it copies the reply alone.",
        SettingsField.LlmContextLength => "The model's context window in tokens, used for the usage percentage. 0 takes the server's own figure.",
        SettingsField.ShowImageThumbnails => "Draws a small colour block of each picture you send under your line, of each picture a tool fetches or makes, and of each `/botchat` picture. `/view` and `/imagine` draw theirs either way.",
        SettingsField.LlmCompactType => "What `/compact` does. `summary` folds the older turns into one summary written by the model. `prune` replaces their bulky tool results with short stubs and keeps every turn. If the server answers a summary request with no text, the app asks once more over a plainer, smaller transcript (tool calls as text lines, long results cut). If that is empty too, the compact fails and says why: the context ran out, the model only thought, or it called a tool.",
        SettingsField.LlmCompactKeepRecent => "How many of the most recent user turns a compact keeps word for word (0–24).",
        SettingsField.LlmAutoCompactPercent => "How full the context window may get before the next message compacts it first (1–100; 0 = off). *LLM tool compact type* acts at the same share during a reply, judged on the next request: the last reported usage plus an estimate of the tool results added since.",
        SettingsField.LlmMaxTurns => "How many user turns the model sees before the oldest drop off (1–500). `auto` keeps them all while auto compact can run (a known context window and a share above 0), and 24 otherwise.",
        SettingsField.LlmToolCompactType => "What happens when one turn's tool calls fill the window up to the *LLM auto compact (%)* share. `compact` prunes first. If the context is still over the share, it summarises the turns before this one, and then, if needed, this turn's earlier tool calls into a progress note (always a summary, whatever *LLM compact type* says). `prune` stubs this turn's older results and carries on. `stop` ends the turn with a notice. `nothing` does nothing.",
        SettingsField.LlmPictureKeep => "The most pictures one request carries (0–500; 0 = no cap). Past it, the oldest pictures leave the conversation until half the cap is left; each becomes a line naming its file, which `view_image` can show again. The newest message's pictures always stay. Every picture is sent again with every request, so a long picture session can outgrow what a server takes in one request.",
        SettingsField.LlmPictureMegabytes => "The most megabytes of pictures one request carries, as sent (0–1000; 0 = no cap). Past it, the oldest pictures leave until half the figure is left, as with *LLM picture keep*. If a server still drops a request with pictures as it is sent, the app takes out half of them and tries once more.",
        SettingsField.LlmOfferTools => "Whether the model gets any tools at all. Turn it off for chat templates with no tool role. Changing it starts a new conversation.",
        SettingsField.LlmMaxToolIterations => "How many tool round trips one message may make before the turn stops (1–10000).",
        SettingsField.ImageThumbnailSize => "`tiny` (32×8), `small` (48×12), `medium` (64×16), `large` (80×20) or `xlarge` (96×24) columns × rows, or `fullsize`: each picture as large as the transcript allows, stacked.",
        SettingsField.FileTreeMaxLength => "How many entries `/tree` prints before it stops (1–10000).",
        SettingsField.FileTreeShowSizes => "`/tree` shows each file's size.",
        SettingsField.NewProfileMode => "What `/profile add` copies from the current profile: `basic` copies the settings and memories; `advanced` also copies the persona, operating-rules and voice-directive files.",
        SettingsField.LlmUseFunVerbs => "The thinking spinner shows a random verb instead of `thinking` / `writing`.",
        SettingsField.LlmScanMode => "Where the app looks for a server while *LLM URL* is blank: `local` (the usual ports on this machine), `remote` (the same ports across the local network), `both`, or `disabled`. With `disabled` nothing is scanned: set the URL by hand, or pick the embedded model or the Anthropic API in `/server`.",
        SettingsField.WebTools => "Offers `web_search`, `web_fetch`, `open_url` and `download_file`.",
        SettingsField.WebBrowserMode => "How pages are fetched. `default` uses the HTTP client and falls back to a headless browser when a page is blocked or empty. `httpclient` never falls back. `chromium` uses the browser for every page. The buttons at the top of the *Web tools* on/off page (D, H, C; the toolbar's 🌐 opens it) switch it too.",
        SettingsField.WebBrowserPath => "The Chromium-based browser used for headless fetches and for making PDFs (`convert_to_pdf`, `/pdf`). Empty finds Edge, Chrome or Brave in their standard folders.",
        SettingsField.WebBrowserNetworkMode => "Where a fetch may reach: `internet` (public addresses only), `local_area_network` (this machine and the LAN only) or `both`.",
        SettingsField.WebSearxngUrl => "A SearXNG instance's base URL, used while the method is `searxng`.",
        SettingsField.WebSearchMaxResults => "How many hits a search returns (1–20).",
        SettingsField.TtsVoicePreview => "The voice pickers (and the preset picker) speak the highlighted voice as you move through them.",
        SettingsField.FileTools => "Offers the sandboxed file tools (read, write, patch, search, move, copy, zip, view_image, image_edit…). They only reach files under the working directory.",
        SettingsField.WebSearchMethod => "`duckduckgo` (built in, no setup) or `searxng` (the instance in *Web SearXNG URL*).",
        SettingsField.AskUser => "Offers `ask_user`, which lets the model ask you multiple-choice questions on the pane.",
        SettingsField.AskMaxQuestions => "How many questions one call may ask (1–10).",
        SettingsField.AskMaxChoices => "How many options one question may offer (2–15).",
        SettingsField.TtsSource => "`in-process` runs the Kokoro voice model inside the app over ONNX Runtime (the model downloads on first use). `http` uses a Kokoro-FastAPI server instead.",
        SettingsField.SttVoskModel => "The Vosk model that listens for the wake word and interrupt: `vosk-model-small-en-us-0.15`, `vosk-model-en-us-0.22-lgraph` or `vosk-model-small-en-in-0.4`.",
        SettingsField.FileMentionFolderMode => "What picking a folder from the `@` list does: `folder-remain` keeps the list open inside it; `folder-apply` writes `@folder/` and closes.",
        SettingsField.AgentSkills => "Lists the skills in the prompt and offers `load_skill` and `skill_editor`. Turning it off also stops the project file being read.",
        SettingsField.ExternalSkills => "Also reads the skills in `%USERPROFILE%\\.agents\\skills`, read-only.",
        SettingsField.SkillCompactMode => "`protected` keeps a loaded skill's instructions through a prune; `unprotected` prunes them like any tool result.",
        SettingsField.TranscriptMarkdown => "Renders replies as Markdown instead of plain text. Code fences in C#, JavaScript/TypeScript, Python, Bash, PowerShell, JSON, YAML, TOML/INI, SQL, C/C++, Java, Kotlin, Go, Rust, CSS, XML/HTML and diff are syntax-highlighted.",
        SettingsField.PastePreviewLines => "How many lines of a long paste show dimmed under its `[Pasted text #n]` placeholder (0–200; 0 = placeholder only).",
        SettingsField.SkillHashMention => "Typing `#` and part of a name on the input line lists the loaded skills; a pick writes `#name` as text.",
        SettingsField.ReflectionAutoLearn => "Lets the app learn from your work: after enough tool calls, or a tool error the model recovered from, a background reflection writes or improves a skill.",
        SettingsField.ReflectionReasoning => "The reasoning effort for the reflection alone: `none`, `low`, `medium`, `high`, `xhigh`, or `profile` for the profile's own level.",
        SettingsField.ReflectionWindow => "How many of the last turns a reflection reads (1–5; the last in full, the earlier ones trimmed).",
        SettingsField.ReflectionMinToolCalls => "How many of the model's own tool calls, counted since the last reflection, make a task worth a skill (3–20).",
        SettingsField.ReflectionMaxRequests => "How many model requests one reflection may spend before it gives up (1–20).",
        SettingsField.HideExitAutocomplete => "Leaves `/exit` out of the `/` list so a stray pick cannot close the app; typing it in full still works.",
        SettingsField.CommandTypoIntercept => "A command name without its slash (`clear`) or with extra slashes (`//profile work`) asks *Did you mean /clear?* before sending it as text. A bare `//` is still `/settings`.",
        SettingsField.WelcomeSplash => "Shows pictures under the banner at startup, until you send the first line: `fullsize` (one picture; ←/→ step through the set), `tiled` (thumbnails at *Image thumbnail size*) or `disabled`. Pictures in the profile's `splash\\` folder replace the built-in ones, and `/splash` shows the splash whatever the setting.",
        SettingsField.ShowHeader => "Shows the banner (the title, the version and the rule under it) at startup and after `/clear`, `/splash`, `/theme` and a profile switch. Off, the screen starts with the transcript. `/new` keeps its own rule either way. `/header` and Ctrl+Alt+H flip it; the change shows at the next clear.",
        SettingsField.ShowWorkingDirectory => "Prints the working directory at the right of the banner's title line.",
        SettingsField.QueueMessages => "Messages sent while a reply streams are listed (as a count, and in `/queue`) and sent when the reply ends. When off, they are still sent then, just not listed.",
        SettingsField.QueueCancelMode => "What a cancelled reply does with the queue: `hold` keeps it until your next message, `drain` sends the next message at once, `empty` drops them all.",
        SettingsField.SessionLogging => "Writes every completed turn to the profile's `sessions.db`, so `/sessions` can list, search and restore it.",
        SettingsField.SessionRetentionDays => "Sessions whose last turn is older than this are deleted at startup (0–3650; 0 = keep forever).",
        SettingsField.SessionNamingMode => "How a session gets its title: `model-written` asks the model for a short name after the first turn; `first-line` uses the first line you sent.",
        SettingsField.SessionShowName => "Which titles show on the rule above the input row: `all-names`, `model-written` (only a name the model wrote or you typed) or `none`.",
        SettingsField.SessionTool => "Offers the model `session_manager`, to search, list and read this profile's earlier sessions (never to restore or purge them).",
        SettingsField.SessionSearchMaxResults => "How many sessions a `session_manager` search or list returns (1–20).",
        SettingsField.ToolsDollarMention => "Typing `$` and part of a name on the input line lists the tools the next turn offers; a pick writes `$name` as text.",
        SettingsField.ReflectionCooldownMinutes => "How long an automatic reflection waits after a reflection wrote a skill (0–1440; 0 = off). Turns that loaded that skill and hit an error after loading it never wait: a fresh skill that failed is worth fixing at once.",
        SettingsField.ReflectionIncludesSessions => "The reflection starts with the earlier sessions that match the turn, and can search them.",
        SettingsField.ReflectionCooldownMode => "`last-written-skill` makes only a turn that used the skill just written wait; `all-skills` makes every automatic reflection wait.",
        SettingsField.DraftEditor => "The program `/draft` opens its temporary file with (`code --wait`, `notepad`…). Empty uses the app Windows opens `.txt` files with.",
        SettingsField.FileViewImageMaxPerCall => "How many pictures one `view_image` call may load (1–100).",
        SettingsField.McpServers => "The master switch. When on, every enabled server starts at launch (and after a profile switch) and its tools are offered. When off, nothing starts.",
        SettingsField.McpConnectTimeoutSeconds => "How long a server gets to finish the handshake and list its tools before it is marked failed (5–300).",
        SettingsField.GitLibTools => "Offers the GitLib tools (`gitlib_status`, …: status, log, show, diff, blame, branch, stage, commit, stash, discard, delete) over the repository in the working directory. They run inside the app, with no `git.exe`. When off, the model reaches git through the shell only, and `/gituser` does nothing.",
        SettingsField.GitLibDiffMaxLines => "Where a `gitlib_diff` patch is cut (20–5000).",
        SettingsField.GitLibLogMaxCommits => "How many commits `gitlib_log` returns unless the call says otherwise (1–200).",
        SettingsField.ShellCommandPolicy => "Whether and how the model may run shell commands through `run_command`. `off`: no shell tools are offered. `ask`: a command not on the allowed list goes to the approval pane first (with no pane, it is refused). `yolo`: everything runs and nothing is asked. See Shell guards.",
        SettingsField.ShellCommandAllowed => "The command prefixes allowed for good (`git status`, `dotnet build`, `python`). Enter on one removes it; the pane's *Allow … always* adds one. The list's ask and yolo buttons (A, Y) switch *Shell command policy*, yolo after a yes. `/cmdlist` opens the list; `/cmdcopy` copies it to another profile.",
        SettingsField.ShellDefault => "The shell `run_command` uses when the call gives no `shell`: `powershell` (pwsh when installed, else Windows PowerShell 5.1), `cmd`, or `bash` (Git Bash, when found).",
        SettingsField.ShellTimeoutSeconds => "How long a foreground command without its own `timeout` may run before it is killed (1–3600).",
        SettingsField.ShellForegroundCapSeconds => "The longest a foreground command may run, whatever its `timeout` says (10–3600).",
        SettingsField.ShellOutputMaxChars => "The most output one result carries back (2000–500000). Past that, the start and end are kept, and the whole text goes to `.shell\\<id>.log` under the working directory, where `read_file` can reach it.",
        SettingsField.ShellCodeLanguages => "The languages `execute_code` may run: `powershell`, `python`, `node`. One or more; a language is offered only while its interpreter is found. Enter or Space turns one on or off, and **A** turns all on. The last one on stays on, so **N** is refused.",
        SettingsField.ShellCodeTimeoutSeconds => "How long an `execute_code` script without its own `timeout` may run before it is killed (1–3600).",
        SettingsField.ShellCodeMaxToolCalls => "How many tool calls one script may make through the bridge (1–500).",
        SettingsField.LlmCompactShowSummary => "After a compact, shows what it did: the summary as dim lines, or one line per pruned tool result, then how many messages were kept at the start and end.",
        SettingsField.GitLibEmail => "The `user.email` that `/gituser` writes into the repository's config. The GitLib tools never read it.",
        SettingsField.GitLibName => "The `user.name` that `/gituser` writes beside it.",
        SettingsField.ShellToolBridge => "Lets an `execute_code` script call the app's other tools through its `neon_tools` module (a loopback socket with a per-run token). When off, no module is written and nothing mentions it, so the script does everything itself.",
        SettingsField.FileBrowserMode => "What the folder browsers (`/cwd browse`, the *Obsidian vault* row) and `/tree` list. `default` hides hidden and system entries and dot-folders (and, in `/tree`, dot-files). `show-hidden` lists them too, except that `/tree` always leaves out `.git` folders.",
        SettingsField.ToolbarItems => "Which items the toolbar under the hint row shows; a double-click on an item runs it. It is a checklist of every glyph (🪪 Profile, 🧮 Themes and 📈 Performance among them, the tool switches from 🐚 Shell to 🖨️ Print, 📄 Log, ⚡ Process (`/process`'s list), 📺 Camera live viewer, 🎞️ Comfy viewer and 🪟 Comfy thumb viewer) and the working-directory path (📂). Enter or Space flips one; **A** / **N** / **D** (or the *select all* / *select none* / *default* buttons) pick all, none or the default ten. With nothing checked the row is hidden. The row reads `all`, `off` or how many are checked. 💾 needs *Memory* on, and the lock and 👮 (🥷 while *Shell police* is off) need a *Shell command policy* other than `off`. A tool switch opens its on/off page (`/tools <group>`) and is drawn on a dark slab while its setting is off; 📄, 📺, 🎞️ and 🪟 open their window, or close it if it is open.",
        SettingsField.ShellPolice => "Refuses a shell command, script or background-process input that names a path outside the working directory. It checks before the command runs or the pane asks. Turning it off asks first, and also stops *Shell police forbidden strings* and the SQLite rule (while *SQLite tools* is on, a command, script or process input that reaches SQLite is refused) and the server-database rule (while *SQL tools*, *Oracle tools*, *MySQL tools* or *PostgreSQL tools* is on, one that reaches that family — its clients and drivers, such as sqlcmd, sqlplus, mysql or psql, or a host its connections name — is refused). `/police` opens this row. See Shell guards.",
        SettingsField.ShellPoliceForbiddenStrings => "Strings the shell police refuses outright: a shell command, script or background-process input that contains one is not run, even under yolo. Case is ignored and any run of spaces, tabs or line breaks counts as one space, so `rm -rf` also catches `RM   -RF`. Enforced only while *Shell police* is on. The model is told the command was refused, not which string; the 👮 line names it for you. The list's top row adds a string; Enter on a string removes it. `/police`'s strings button (S) opens it too. A tripwire, not a sandbox: text built in pieces gets past it.",
        SettingsField.ToolCollapseCount => "A run of more tool calls than this folds under one summary line (`▸ 🛠️ 7 tool calls — read_file ×3, …`). A call and its result count as one. Only its last calls show while it runs, and only the summary afterwards (0–100; 0 = never fold).",
        SettingsField.CodeCollapseCount => "A top-level code block longer than this folds to its label (`▸ 📜 csharp · 57 lines`) once its closing fence arrives. While streaming, only its last this-many lines show (0–100; 0 = never fold). Needs *Transcript markdown*.",
        SettingsField.ShowFileDiffs => "A file edit (`patch_file`, `write_file`, `unc_patch`, `unc_write`) shows its diff under its line: `└ Added 3 lines, removed 1 line`, then the changed lines numbered with three of context, added ones on a green slab, removed ones on a red, coloured by the file's language. It folds with the tool run. Off: the one line. The model's result is the same either way.",
        SettingsField.DiffMaxLines => "The most rows of an edit's diff shown; past it `… 12 more lines` ends it (0–500; 0 = the header line alone).",
        SettingsField.DiffCollapseCount => "An edit's diff of more rows than this (counted over the whole diff, past *Diff max lines* too) shows open while its tool run goes on, then folds to `▸ Added 3 lines, removed 1 line · 14 rows` once the run is over (0–500; 0 = never fold).",
        SettingsField.ObsidianTools => "Offers the vault tools (search, list, read, links, daily, write, properties, move) over the vault in *Obsidian vault*, once one is set.",
        SettingsField.ObsidianVault => "The vault's folder (the one holding `.obsidian`). It is separate from the working directory. Editing the row opens the `/cwd browse` folder picker.",
        SettingsField.ObsidianAllowDelete => "Offers `vault_delete`, which moves a note or attachment into the vault's `.trash` (never deleted for good).",
        SettingsField.SqlTools => "Offers the SQL tools (connections, databases, tables, columns, describe, relationships, indexes, query) over the connections in `sql.json`, once one is defined. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *SQL connections offered*.",
        SettingsField.SqlMode => "`read-only`: the SQL tools only read. `read-write`: `sql_execute` is offered too, on the connections whose entry in sql.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *SQL statements allowed* ticks (changing data, creating and reading by default), committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection and database, until the session ends); a read asks nothing and runs read-only. BEGIN TRAN/COMMIT, SET, USE, GRANT/DENY/REVOKE, logins, users and roles, DBCC, BACKUP/RESTORE, BULK INSERT, OPENROWSET and the other doors out, linked servers, xp_ and sp_configure, dynamic SQL (EXEC of a string, sp_executesql) and CREATE or DROP of a database stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.SqlStatementsAllowed => "Under *SQL mode* `read-write`: the kinds of statement `sql_execute` may run, ticked on a checklist — changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE TABLE, a MERGE that deletes), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, TYPE, SCHEMA, SYNONYM), changing structure (ALTER TABLE, INDEX, VIEW, SEQUENCE, SCHEMA; sp_rename is a procedure), dropping (DROP …), upkeep (UPDATE STATISTICS), procedures and triggers (EXEC of a procedure, and making or changing a procedure, function or trigger, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. A / N / D pick all, none or the default (changing data, creating, reading). With none ticked, `sql_execute` is not offered.",
        SettingsField.SqlDefaultConnection => "The connection used when a call names none: one of the offered connections, or the first. A call can still name another offered connection, and `database` can open other databases on the same server.",
        SettingsField.SqlQueryMaxRows => "How many rows `sql_query` returns unless the call says otherwise (1–100000). Past that, the header says more exist.",
        SettingsField.SqlQueryTimeoutSeconds => "How long one SQL tool's batch may run on the server (1–600).",
        SettingsField.SqlConnectionsProfile => "Enter opens the profile's `sql.json` in your editor (created with a commented example of each sign-in kind). The value shows how many connections it has.",
        SettingsField.SqlConnectionsGlobal => "Enter opens the home folder's `sql.json`, which every profile reads, in your editor. The profile's wins on a name clash.",
        SettingsField.SqlSetPassword => "Pick a connection that takes a password (`sql` or `runas`) and type it, masked. It is saved to that connection's store: encrypted in its `sql.json`, or in Windows Credential Manager.",
        SettingsField.SqlPercentMention => "Typing `%` and part of a name on the input line lists the connections (server, database, description); a pick writes `%name` as text.",
        SettingsField.SqlConnectionsOffered => "A checklist of the connections in both `sql.json` files. Nothing is offered until you tick it here or offer it from the add-connection wizard, and a connection added later stays hidden until ticked. **A** / **N** tick all or none (\"all\" means the ones listed now). A hidden connection is invisible to every SQL tool, the rules, the `%`-mention and the default (`sql_connections` says how many are hidden, never which). A ticked name no longer in the files is dropped when the checklist opens, and the status line names it; not while a file cannot be read, nor a name an entry with a problem still holds.",
        SettingsField.SqlAddConnection => "A wizard for a new connection, one page per choice, or to edit a saved one. It can **test** the draft (`SELECT @@VERSION`) before saving it. With entries saved, its first page lists them: + New, or one to edit, which opens on its summary prefilled (Enter on a row changes it; its file kept, the stored password kept unless another is typed). See Managing connections.",
        SettingsField.Theme => "One of the built-in themes (sixty, in categories such as cinema, machines and nights, from the repo's `assets/themes`) or your own from the `themes` folder, all listed by name; a file of yours named like a built-in replaces it (see Custom themes).",
        SettingsField.ComfyTools => "Offers the image tools (`generate_image`, `set_splash_image`), once *ComfyUI URL* is set and a workflow is in a `comfy` folder. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *ComfyUI workflows offered*.",
        SettingsField.ComfyUrl => "The ComfyUI server, often another machine on your LAN (`http://gpu-box:8188`). As with the LLM server, the web tools' network mode never blocks it.",
        SettingsField.ComfyTimeoutSeconds => "How long the tool waits for one generation, queue included (10–3600). The job may still finish in ComfyUI.",
        SettingsField.ComfyOutputFolder => "The folder under the working directory the pictures are saved in (`comfy_images\\pony-txt2img-1234.png`). Empty uses the working directory itself.",
        SettingsField.ComfyWorkflowsOffered => "A checklist of the installed workflows the model is offered. Nothing is offered until you tick it here or offer it from the add-workflow wizard, and a workflow added later stays hidden until ticked. **A** / **N** tick all or none (\"all\" means the ones installed now). With one ticked, every plain request and a plain `/imagine` go to it. `/imagine <name>` can still use a hidden one. A ticked workflow no longer installed is dropped when the checklist opens (not one whose file failed to load), and the status line names it.",
        SettingsField.ComfyAddWorkflow => "A wizard that **builds** a standard workflow from your server's checkpoints, or **imports** one you exported from ComfyUI. See Adding a workflow.",
        SettingsField.ImageEditor => "Where a double-clicked picture opens. Empty: the built-in picture viewer. `system`: the app Windows registers for the file type (Paint for png, jpg and bmp). Anything else is a command, with the file's path appended (`mspaint`, `\"C:\\Program Files\\GIMP 3\\bin\\gimp-3.exe\"`).",
        SettingsField.ComfyMaxPicturesPerCall => "The most pictures one `generate_image` call or `/imagine --count` makes (1–16). Each is a full job, and all of them go to the model in the next request, where a local vision server has its own limit.",
        SettingsField.ComfyReinforceNegatives => "When the model writes the prompt, it also adds a few opposite tags to the workflow's negative prompt where the image model tends to drift (a solo figure → `multiple girls`, night → `daylight`). Skipped for a verbatim prompt, a negative set for the call, `/imagine`, families without a negative (Flux, FLUX.2, Klein, Krea 2, Z-Image, Ernie Turbo, Boogu, Ideogram 4) and a workflow whose `.md` says `reinforce: false`.",
        SettingsField.ComfyShowPrompts => "Shows what was sent under each picture: the `prompt:`, the `negative:` and a `params:` line (size, steps, cfg, denoise, seed, sampler, scheduler). When off, only the picture's line shows. The model sees the same either way.",
        SettingsField.ComfyCaretMention => "Typing `^` and part of a name on the input line lists the offered workflows (family, shape, size). A pick writes `^name`, which `generate_image` reads as the workflow to use.",
        SettingsField.ComfyPictureStrip => "Keeps the session's ComfyUI pictures as thumbnails in a strip above the input line, newest at the left by when each file was made, the same order as the picture viewer. With the input line empty, ←/→ highlight one and Enter opens it, whether or not a reply is running. A double-click opens any, and dragging one onto the input row attaches it to your message. The **🎞️** at the left of the strip's rule opens the picture viewer on the output folder. The **×** at its right hides the strip until the next picture (turn this setting off to keep it hidden); meanwhile a **🎞️** on the rule over the input row, right of ⤡, brings it back. `/clear`, `/new` and a session switch empty it; it hides while a menu is open or the window is too short.",
        SettingsField.ReflectionYieldsToTurns => "A message sent while a reflection runs pauses it, so the reply gets the server. The same reflection runs again once the reply and any queued messages are done. Turn it off if your server handles requests in parallel.",
        SettingsField.BotChatComfy => "Gives the bots this profile's *ComfyUI workflows offered* for pictures. When off, *Botchat ComfyUI limited workflows* decides; with neither, the chat is talk alone. Of the set, the text → image workflows draw new pictures and the image → image ones rework the chat's pictures (other kinds are skipped); with several of a kind, the `automatic` prompt writer picks one by name. Needs *ComfyUI tools* on and a *ComfyUI URL*. The main chat's own `generate_image` is never among the bots' tools.",
        SettingsField.BotChatLimitedComfyWorkflows => "The ComfyUI workflows the bots get while *Botchat ComfyUI enabled* is off: tick them in the checklist (**A** / **N** for all or none), any installed workflow, offered to this chat or not. With none ticked, no pictures. A ticked workflow no longer installed is dropped when the checklist opens, as on *ComfyUI workflows offered*.",
        SettingsField.BotChatImageMode => "Who draws. `automatic`: the app writes a prompt from each reply and draws it. `autonomous`: the bots get `generate_image` over the Botchat ComfyUI workflows and draw when they choose. See Botchat pictures.",
        SettingsField.BotChatImageAsync => "On: the next bot speaks while the picture renders, and the picture appears when nothing is streaming. Off: each reply is held back until its picture is drawn, then appears under it.",
        SettingsField.BotChatLlmMode => "Whose LLM the bots use. `single`: every bot uses this profile's server, model and reasoning. `multi`: each bot uses its own profile's URL, model, API key, timeouts and reasoning (a blank URL borrows this profile's server). A bot whose server does not answer at the start sits the chat out, with a notice. Read when a chat starts or resumes.",
        SettingsField.LlmMidTurnUsage => "What the token usage on the hint row shows during a reply. `estimate`: context and tok/s update live, marked `~` (counting one token per streamed chunk), until the server's figures arrive at the end of each request. `last-known`: the figures from the last completed request.",
        SettingsField.KeepCommandHistory => "Saves the ↑/↓ history (newest 1,000 lines) in the profile's `sessions.db`, so it survives restarts and profile switches. Lines holding a collapsed paste or a picture are not saved. When off, the saved lines are deleted the next time the profile loads. `/cmdclear` empties it either way.",
        SettingsField.BotChatNonTtsDelaySeconds => "Seconds to pause after each reply when no voice plays (*TTS output* off), so there is time to read it (0–30; 0 = no pause). A line you send meanwhile, or one queued while the bot was replying, ends the pause and goes to the bots at once; ESC during the pause ends the chat.",
        SettingsField.ShellPreferNative => "Steers the model to the app's own tools. A single shell command that one of them covers is sent back to the model (once a turn). See Shell guards.",
        SettingsField.LlmShowThinking => "Streams a reasoning model's thinking as a dim block (its last five lines). When the answer starts, the block folds to `▸ 💭 thought for 4.2s`. Click that line, press Ctrl+O or use `/expand` to see it again. Needs *Transcript markdown*. Thinking is never spoken or logged, and only `/copy --thinking` copies it.",
        SettingsField.ClaudeCliExecutable => "The Claude Code CLI to run. Blank looks for `claude.exe` on the PATH, then npm's `claude.cmd`, then `%USERPROFILE%\\.local\\bin\\claude.exe` (where the native installer puts it). A path you set must exist; it is never swapped for another.",
        SettingsField.ClaudeCliPermissions => "What Claude may do during a `/claude` run. `read-only`: `Read`, `Grep`, `Glob`, `WebSearch`, `WebFetch`. `edit`: its usual tools with file edits accepted, commands denied. `full`: everything, commands included (`bypassPermissions`). Nothing is ever asked: anything outside the level is denied, and the reply lists what was. Claude works in the working directory, but outside the app's sandbox, shell policy and approval pane. The advisor is always `read-only`.",
        SettingsField.ClaudeCliModel => "The `--model` for `/claude`: Claude Code's default, `fable`, `opus`, `sonnet` or `haiku` (the latest of each), or *Other…* to type a model name.",
        SettingsField.ClaudeCliEffort => "The `--effort` for `/claude`: Claude Code's default, `low`, `medium`, `high`, `xhigh` or `max`.",
        SettingsField.ClaudeCliAdvisor => "Offers the model `claude_advisor_cli`, to ask Claude Code for read-only advice when it is stuck. Each call costs money on your Claude account.",
        SettingsField.ClaudeCliAdvisorContext => "What a call sends. `brief`: the model's question and context. `recent`: also the last 10 messages (tool results cut to 500 characters). Either way, Claude can read the working directory itself.",
        SettingsField.ClaudeCliAdvisorCallsPerTurn => "The most advisor calls one reply may make (1–10). Past that, the model carries on alone.",
        SettingsField.ClaudeCliAdvisorModel => "The `--model` for the advisor. The first row follows *Claude CLI slash command model*.",
        SettingsField.ClaudeCliAdvisorEffort => "The `--effort` for the advisor. The first row follows *Claude CLI slash command effort*.",
        SettingsField.ClaudeCliAdvisorConfirm => "Each call waits for your yes on the pane (the cursor starts on No; ESC means no). A no tells the model to carry on without it. In a headless run, calls are refused.",
        SettingsField.AnthropicApi => "Offers the Anthropic API on `/server` while a key is set. If it is off (or has no key) while the Anthropic API is the saved LLM URL, the app scans for a server as if the URL were blank.",
        SettingsField.AnthropicApiKey => "Your Anthropic API key (`sk-ant-…`), saved encrypted for your Windows account (DPAPI) and shown as `(set, encrypted)`. Typing replaces it; an empty entry clears it.",
        SettingsField.AnthropicApiMaxTokens => "The output cap per request, thinking included (1,024–128,000). A reply that hits it stops short, and the log says so.",
        SettingsField.AnthropicApiPromptCaching => "Marks the tools, system prompt and conversation for Anthropic's prompt cache. Each request then re-reads the previous one's content at a fraction of the price.",
        SettingsField.OpenAIApi => "Offers the OpenAI API on `/server` while a key is set (over the Responses API, with the reasoning shown as OpenAI's summary; every message is billed). If it is off (or has no key) while the OpenAI API is the saved LLM URL, the app scans for a server as if the URL were blank. Sampling settings are not sent to it.",
        SettingsField.OpenAIApiKey => "Your OpenAI API key (`sk-…`), saved encrypted for your Windows account (DPAPI) and shown as `(set, encrypted)`. Typing (masked) replaces it; an empty entry clears it. It goes only to api.openai.com, never to a local server or the Anthropic API.",
        SettingsField.OpenAIApiMaxTokens => "The output cap per request, reasoning included (`max_output_tokens`): 0 sends none and the model's own limit applies, else 1,024–128,000. A reply that hits it stops short, and the log says so.",
        SettingsField.OpenAIApiOrganization => "The organization a request is billed to (the `OpenAI-Organization` header), for an account in several. Empty sends none: the key's default organization.",
        SettingsField.OpenAIApiProject => "The project a request is billed to (the `OpenAI-Project` header). Empty sends none: a project key already names its project.",
        SettingsField.BotChatSkills => "Offers every bot `load_skill` (never `skill_editor`) over the skills this chat can see: the starting profile's, the global ones and, with *Use external skills*, the external ones, but never a bot's own profile's. In `automatic` mode the prompt writer gets them too. When off, *Botchat limited skills* decides. Needs *Agent skills*; switching `load_skill` off in `/tools` turns this off too.",
        SettingsField.BotChatVision => "On its turn, shows each bot the newest 4 pictures since it last spoke (not the ones it drew itself), each captioned with whose it is. Only for models that read images: a text-only server fails the turn (in `multi` mode, every bot's model counts). Pictures are not kept for `/botchat --resume` or the saved session.",
        SettingsField.ThemedExternalWindows => "The app's own windows (the built-in picture viewer, the camera's live window and the log window) wear the theme: a themed dark title bar (Windows 11; Windows 10 gets a plain dark one) and the theme's background and colours. When off, they stay black.",
        SettingsField.ThemedBackground => "The terminal's page takes the theme's background colour while the app runs, and gets its own back when the app exits. When off, the terminal profile's background (a colour scheme, acrylic or a picture) stays as it is.",
        SettingsField.ReflectionEditsSupportingFiles => "Lets a reflection also change a skill's supporting files (the data, examples or scripts beside its `SKILL.md`) with `skill_editor`'s `write_file` and `edit_file`. When off, a reflection writes the `SKILL.md` alone; the main chat may always write them.",
        SettingsField.BotChatImg2ImgMode => "Which pictures a rework may start from: the `latest` one, or any in `chat-history` (the last 8, numbered). Only while the Botchat ComfyUI workflows include an image → image one.",
        SettingsField.BotChatLimitedSkills => "The skills the bots may load while *Botchat skills enabled* is off: tick them in the checklist (**A** / **N** for all or none). With any ticked, every bot (and, in `automatic` mode, the picture prompt writer) is offered `load_skill` for those skills alone; with none, no skill tool. Needs *Agent skills*. A ticked skill not listed now (external skills off, another folder's own) is skipped, and shows after the others as *not available now*: untick it there, or **N** clears it with the rest.",
        SettingsField.BotChatTools => "Offers every bot the tools a turn of this chat would get: the same tool switches, `/tools` list and panes (the shell's approval, the Docker, Home Assistant and print confirms, `ask_user`, the camera's shutter), and while you plan only plan mode's read-only tools. Not memory, skills or the ComfyUI tools: their own Botchat rows say. When off, *Botchat limited tools* decides.",
        SettingsField.BotChatLimitedTools => "The tools the bots get while *Botchat tools enabled* is off: tick them in the checklist, grouped as on `/tools` (**A** / **N** for all or none). A ticked tool is offered only while this chat would offer it too (its switch on, not off in `/tools`). With none ticked, no tools. The ComfyUI tools are not listed: the Botchat ComfyUI rows say. A ticked tool not listed now (an MCP server not connected) shows at the end under *Not available now*: untick it there, or **N** clears it with the rest.",
        SettingsField.BotChatMemory => "Gives every bot memories: the list in its prompt, and `save_memory` and `recall_memory`. Inside `/botchat` this alone decides, over every profile's *Memory* switch (the starting profile's too). *Botchat memory mode* says whose memories.",
        SettingsField.BotChatMemoryMode => "Whose memories the bots use: `shared-parent` (every bot the starting profile's) or `independent` (each bot uses its own profile's; the starting profile's bot uses the starting profile's).",
        SettingsField.LlmPreserveThinking => "Sends the model's thinking from earlier turns back to a local server, as `reasoning_content`, and asks the chat template to keep it (`chat_template_kwargs`: `preserve_thinking` for Qwen3.6, `clear_thinking: false` for GLM). The current turn's thinking is always sent back, so a model keeps its reasoning between tool calls. This costs context; a `/compact` prune drops older thinking first. The Anthropic API is not affected.",
        SettingsField.SessionSaveThinking => "Saves each reply's thinking with the session, so a resumed session can send it back when *LLM preserve thinking* is on. Leave it off to keep `sessions.db` smaller; thinking saved earlier is still read back.",
        SettingsField.LlmSampling => "Sampling overrides per model (temperature, top_p, top_k, min_p, the penalties, an extra body). The row lists the models that have some; Enter opens the `/sampling` pane. See Sampling per model.",
        SettingsField.LlmSamplingFromHuggingFace => "Shows a model's recommended sampling when the server does not report its own defaults (vLLM, SGLang, LM Studio) and the model id is a Hugging Face repo (`Qwen/Qwen3-8B`). The `/sampling` pane then reads the model card's `generation_config.json` and shows its values as `(Hugging Face)`. vLLM and SGLang use that file unless started otherwise. It makes one request to huggingface.co per model and connect, never with your API key, and is for display only.",
        SettingsField.HomeAssistantTools => "Offers the Home Assistant tools (`ha_overview`, `ha_states`, `ha_history`, `ha_lights`, `ha_scene`, `ha_media`, `ha_todo`, `ha_call_service`, `ha_assist`), once a URL and a token are set.",
        SettingsField.HomeAssistantUrl => "Your Home Assistant server (`http://localhost:8123`, or another machine on your LAN). As with the LLM server, the web tools' network mode never blocks it.",
        SettingsField.HomeAssistantToken => "A long-lived access token (in Home Assistant: your profile → Security → Long-lived access tokens). It is typed into a masked field and saved encrypted (DPAPI) for your Windows account; empty clears it. Never written to the log.",
        SettingsField.HomeAssistantTest => "Asks the server for its version with the saved URL and token, and shows the answer.",
        SettingsField.HomeAssistantActionPolicy => "What the model may switch. `off`: it only reads. `ask`: lights, scenes, the TV's power, volume, source and playback, and to-do lists run; anything else (a remote key, a button, a switch, a script, an automation, a restart) waits for your yes on the pane. In a headless run, those calls are refused. `allow`: everything runs. `/ha` never asks.",
        SettingsField.HomeAssistantAssistAgent => "The conversation agent `ha_assist` and `/ha say` talk to (e.g. `conversation.google_generative_ai`). Empty uses Home Assistant's default.",
        SettingsField.HomeAssistantTimeoutSeconds => "How long one request may take (2–60).",
        SettingsField.YouTubeTools => "Offers the YouTube tools: `youtube_search` (with a YouTube API key set) and `youtube_play`, `youtube_control` and `youtube_status`, which play a video in the app's video window (Windows, with the WebView2 Runtime Windows 11 has). Playing by a video's id or link needs no key. A headless run offers the search alone. `/youtube` works either way.",
        SettingsField.YouTubeApiKey => "Your YouTube Data API v3 key, for searching. Make one in the Google Cloud Console: create a project, enable YouTube Data API v3 (APIs & Services › Library), create an API key under Credentials and restrict it to that API, with no application restriction. A search costs 100 of the project's 10,000 free units a day (about 100 searches). Typed into a masked field and saved encrypted (DPAPI) for your Windows account; empty clears it. `/keycopy` copies it and a plain `/profile reset` keeps it. Never written to the log.",
        SettingsField.YouTubeSearchMaxResults => "How many videos a search lists (1–20), for the model and in `/youtube`'s picker. The quota cost is the same whatever the count.",
        SettingsField.YouTubeAutoplay => "Whether a played video starts at once, sound included, or waits cued until you or the model press play.",
        SettingsField.YouTubeVoice => "What a playing video does while the app speaks a reply (from its first word to its last) or listens to you (push-to-talk, or after the wake phrase). `pause`: it pauses and plays on after. `duck`: it turns down to 15% and back up after (speech input still hears it). `none`: it plays on. Only what the app did is undone: a video you paused stays paused.",
        SettingsField.PrintTools => "Offers `list_printers` and `print_file` to the model. `/print` works either way.",
        SettingsField.PrintActionPolicy => "What the model may print. `off`: it may list the printers but never print. `ask`: every print waits for your yes on the pane, which names the file, the printer, the pages and the copies; in a headless run, it is refused. `allow`: it prints without asking. `/print` never asks.",
        SettingsField.PrintDefaultPrinter => "The printer a print goes to when none is named, picked from the installed printers.",
        SettingsField.PrintFontSize => "The body text size for a printed listing or Markdown file (6–24); headings scale from it.",
        SettingsField.PdfEngine => "What makes a PDF for `convert_to_pdf` and `/pdf`. `auto`: Edge, Chrome or Brave when one is found, else Microsoft Print to PDF, which also takes over when the browser fails. `browser`: the browser only. `printer`: Microsoft Print to PDF only, so Markdown, text and pictures in black and white, never HTML or a web page.",
        SettingsField.EmbeddedModels => "The catalog: each model with its size and state. The title row's buttons filter it. **8GB** and **16GB** (keys 1, 2) keep the models at most that big by the size a row shows (weights, vision projector and drafter), one at a time (press the lit one again to clear it). **installed** (I) and **uninstalled** (U) keep the models on disk or the others, also one at a time (a paused download counts as uninstalled). **drafter** (D) keeps the models with a drafter (their own or built in; see the catalog's Drafter column). **sort (name)** (S) says the models are in the catalog's name order; pressing it orders them by size, smallest first by the size a row shows, and the button then reads **sort (size)**. Pressing it again goes back to name order. The uncensored builds are hidden until you press **uncensored** (X), the last button: then only the uncensored builds show, and pressing it again goes back to only the others. Each group combines with the others, and all start cleared at each visit, except that uncensored starts lit when the model in use is an uncensored build, so its row shows. `/server` and the startup picker have the size, drafter, sort and uncensored buttons (their rows are all installed), which thin and order only their embedded rows. Enter on an installed model offers *Use now* and *Remove*; on any other, *Install*, plus *Remove* for a partly downloaded one. Remove asks first, stops a download of that model and any server running it, and deletes its folder; if it was the saved LLM, the LLM URL and model are cleared. Using or installing a model closes the settings and connects.",
        SettingsField.EmbeddedBackend => "Which llama.cpp build runs the model: `auto` (CUDA with an NVIDIA driver 580 or newer, else Vulkan, else the CPU), `cuda`, `vulkan` or `cpu`. The row shows what `auto` picked and why.",
        SettingsField.EmbeddedContextSize => "The server's context window in tokens (how much conversation the model can hold). 0 means **fit**: the largest context that fits beside the model with every layer on the GPU (within *Embedded VRAM budget*), from the model's own window (128K for Gemma 4 E2B/E4B, 256K for the larger models) down to 4,096. Otherwise 512–262,144, which is never shrunk. A profile that saved 32,768 (the default before fit) keeps it.",
        SettingsField.EmbeddedGpuLayers => "How many of the model's layers go on the GPU: `auto` (as many as the free VRAM holds), `all`, or a number (0 runs on the CPU).",
        SettingsField.EmbeddedVision => "Loads the model's vision projector so it can read images (about 1 GB more memory for most models, under 200 MB for the 12Bs, 2 GB for Muse Glimmer). When off, an image sent to the embedded model is refused.",
        SettingsField.LlmReasoningEstimate => "How the *Reasoning* count in `/usage` is filled in when the server streams the model's thinking but does not count it (llama.cpp, including the embedded LLM, and Ollama). `chars` divides the thinking's characters by 4. `tokenize` asks llama.cpp's `/tokenize` for the exact count (one short request after each reply), and falls back to `chars` where that is not available. `off` shows `—`. An estimate shows as `~1,234`. When the server gives its own count, that is always used as it is.",
        SettingsField.EmbeddedLlmServer => "Offers the embedded models. When off, `/server` lists none and `/server embedded` refuses. A saved embedded URL counts as none (the app looks for a server as if the URL were blank), and a running embedded server stops. Installed models stay on disk.",
        SettingsField.EmbeddedDrafter => "Speeds up replies with multi-token prediction (MTP): the model drafts a few tokens ahead and then checks them, so the text is the same, just faster. Gemma 4 models use a small drafter file, downloaded with the model (or at its next start, for a model installed before). Qwen3.8 has the drafter built in. Muse Glimmer uses a DFlash drafter instead, a 1.6 GB file that drafts 16 tokens at a time. The catalog's Drafter column says which each model has. When off, no drafter is loaded (nor downloaded with a new install) and the model writes one token at a time. Turn it off if a model misbehaves with it.",
        SettingsField.ShowPerformanceBar => "A checklist of the meters the bar under the toolbar shows, updated once a second: **CPU**, **RAM**, **GPU**, **VRAM**, **NET** (network use, as a share of the link speed), **NET↓** and **NET↑** (the download and upload rates), and **PROC** (the model's background processes still running, a number in every look; `/process` lists them). Enter or Space flips one; with none checked there is no bar. **A** / **N** / **D** (or *select all* / *select none* / *default*) check all, none or the default four (CPU, RAM, GPU and VRAM). The look is on the same screen's title row: **text** (T, the numbers), **gauge** (G, a bar per meter), **spark** (S, the last ten seconds as a sparkline) or **led** (L, ten segments in the theme's colours); the one in use is lit. Values turn amber from 60 % and red from 85 %. An NVIDIA GPU is read through its driver (NVML); any other through Windows' own GPU counters, for the card with the most memory. The network meters show the busiest of the adapters that are up and have a gateway, so a VPN on top of Wi-Fi, or Wi-Fi beside Ethernet, is not counted twice and NET is the share of that adapter's own link; NET↓ and NET↑ show bits per second (`850K`, `12.4M`, `1.2G`), and their gauge, sparkline and LEDs are their share of the link speed. A meter the machine cannot read (no GPU, no network) is left out. The bar is centred on its row, and each value keeps its width so nothing shifts as it changes. The row reads `off`, or the checked meters and the look (`CPU, RAM · gauge`). `/perfbar` or the toolbar's 📈 hides the bar, or shows it again with the meters it last had (CPU, RAM, GPU and VRAM the first time).",
        SettingsField.EmbeddedVramBudget => "How much of the GPU's memory the embedded server may fill: `off` (llama.cpp leaves 1 GiB free on each GPU) or 50–99 % of the card with the most memory, leaving the rest free for other programs. A profile that saved `off` (the default until it became 91 %) keeps it. The budget only adjusts what is left to fit: *Embedded context size* 0 (the context shrinks first) and *Embedded GPU layers* `auto` (then layers move to the CPU). If you set a context too big for the budget, layers are all it can move and replies slow down sharply, so it works best with context 0. The budget is measured when the server starts; memory other programs take later is not held back. CUDA and Vulkan only; a change restarts the server.",
        SettingsField.EmbeddedHfDownloadType => "How a model's files are downloaded from Hugging Face. `parallel` fetches each file over 8 connections at once (about twice as fast as one) and joins the parts before the checksum. `single` uses one connection. A download already under way carries on the way it started.",
        SettingsField.BotChatMultiEmbedded => "Only with *Botchat LLM mode* `multi`. It decides what a bot gets when its profile names a different embedded model from the one running. `parent-server`: one embedded server; the bot uses the running model (this profile's, or with none running, the first embedded bot's), with a warning naming the model it wanted. `multi-server`: an extra `llama-server` for each other embedded model. They start one after another, each under that bot's profile's Embedded settings (backend, context, GPU layers, VRAM budget, vision, drafter), so each fits into the memory the ones before it left. The running server is never restarted, and a bot whose server does not start sits the chat out. Two bots on one model share its server.",
        SettingsField.BotChatMultiEmbeddedKill => "On: the extra servers from `multi-server` stop when the chat ends, however it ends. Off: they keep running until `/botchat --kill` or you quit, and a later botchat naming the same models reuses them.",
        SettingsField.ClaudeCliServer => "Offers Claude Code on `/server` while it is found (*Claude CLI executable*, or the PATH). If it is off (or Claude Code is gone) while the Claude CLI is the saved LLM URL, the app scans for a server as if the URL were blank, and a running Claude CLI stops.",
        SettingsField.OracleTools => "Offers the Oracle tools (connections, schemas, tables, columns, describe, relationships, indexes, query) over the connections in `oracle.json`, once one is defined. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *Oracle connections offered*.",
        SettingsField.OracleMode => "`read-only`: the Oracle tools only read. `read-write`: `oracle_execute` is offered too, on the connections whose entry in oracle.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *Oracle statements allowed* ticks (changing data, creating and reading by default), committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection and schema, until the session ends); a read asks nothing and runs read-only. COMMIT/ROLLBACK/SAVEPOINT/SET TRANSACTION, ALTER SESSION/SYSTEM, GRANT/REVOKE, users, roles, profiles, tablespaces, directories, database links (@ anywhere), LOCK TABLE, EXECUTE IMMEDIATE, RETURNING … INTO and the denied packages (UTL_FILE, UTL_HTTP, DBMS_SQL, DBMS_SCHEDULER…) stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.OracleStatementsAllowed => "Under *Oracle mode* `read-write`: the kinds of statement `oracle_execute` may run, ticked on a checklist — changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE, a MERGE that deletes), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, SYNONYM, TYPE), changing structure (ALTER TABLE, INDEX, VIEW, SEQUENCE; RENAME; COMMENT ON), dropping (DROP …), upkeep (ANALYZE), procedures and triggers (CALL, an anonymous BEGIN … END or DECLARE block, and making or changing a procedure, function, package, trigger or type body, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. A / N / D pick all, none or the default (changing data, creating, reading). With none ticked, `oracle_execute` is not offered.",
        SettingsField.OracleConnectionsOffered => "A checklist of the connections in both `oracle.json` files, as *SQL connections offered* is for `sql.json`: nothing until ticked.",
        SettingsField.OracleDefaultConnection => "The connection used when a call names none: one of the offered connections, or the first. A call can still name another, and `schema` works in another schema.",
        SettingsField.OracleSetPassword => "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `oracle.json`, or in Windows Credential Manager.",
        SettingsField.OracleAddConnection => "A wizard for a new connection, one page per choice, or to edit a saved one (as SQL add/edit connection does). It can **test** the draft before saving it: who it signs in as, the server's version, and a warning when the account could change data. See Oracle.",
        SettingsField.OraclePercentMention => "Typing `%` and part of a name also lists the Oracle connections, each marked `Oracle ·`; a pick writes `%name` as text.",
        SettingsField.OracleQueryMaxRows => "How many rows `oracle_query` returns unless the call says otherwise (1–100000). Past that, the header says more exist.",
        SettingsField.OracleQueryTimeoutSeconds => "How long one Oracle tool's statement may run on the server (1–600).",
        SettingsField.OracleConnectionsProfile => "Enter opens the profile's `oracle.json` in your editor (created with commented examples). The value shows how many connections it has.",
        SettingsField.OracleConnectionsGlobal => "Enter opens the home folder's `oracle.json`, which every profile reads, in your editor. The profile's wins on a name clash.",
        SettingsField.MySqlTools => "Offers the MySQL tools (connections, databases, tables, columns, describe, relationships, indexes, query) over the connections in `mysql.json`, once one is defined. They work against MySQL 8.0.16+ and MariaDB 10.2+. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *MySQL connections offered*.",
        SettingsField.MySqlMode => "`read-only`: the MySQL tools only read. `read-write`: `mysql_execute` is offered too, on the connections whose entry in mysql.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *MySQL statements allowed* ticks (changing data, creating and reading by default), committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection and database, until the session ends); a read asks nothing and runs read-only. START TRANSACTION/COMMIT, SET, USE, GRANT/REVOKE, LOAD DATA, INTO OUTFILE, LOCK, PREPARE/EXECUTE, HANDLER, FLUSH/KILL, DEFINER = and CREATE or DROP of a database, user, role, server or event stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.MySqlStatementsAllowed => "Under *MySQL mode* `read-write`: the kinds of statement `mysql_execute` may run, ticked on a checklist — changing data (INSERT, UPDATE, REPLACE), deleting (DELETE, TRUNCATE), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE), changing structure (ALTER TABLE, VIEW, SEQUENCE; RENAME TABLE), dropping (DROP …), upkeep (ANALYZE, OPTIMIZE, CHECK, REPAIR, CHECKSUM TABLE), procedures and triggers (CALL, and making or changing a procedure, function or trigger, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it. A / N / D pick all, none or the default (changing data, creating, reading). With none ticked, `mysql_execute` is not offered.",
        SettingsField.MySqlConnectionsOffered => "A checklist of the connections in both `mysql.json` files, as *SQL connections offered* is for `sql.json`: nothing until ticked.",
        SettingsField.MySqlDefaultConnection => "The connection used when a call names none: one of the offered connections, or the first.",
        SettingsField.MySqlSetPassword => "Pick a connection and type its password, masked. It is saved to that connection's store: encrypted in its `mysql.json`, or in Windows Credential Manager.",
        SettingsField.MySqlAddConnection => "A wizard for a new connection, or to edit a saved one (as SQL add/edit connection does). It can **test** the draft before saving it: who it signs in as, the server's version, and a warning when the account's grants could change data. See MySQL.",
        SettingsField.MySqlPercentMention => "Typing `%` and part of a name also lists the MySQL connections, each marked `MySQL ·`.",
        SettingsField.MySqlQueryMaxRows => "How many rows `mysql_query` returns unless the call says otherwise (1–100000).",
        SettingsField.MySqlQueryTimeoutSeconds => "How long one MySQL tool's statement may run (1–600), enforced on the server and by the driver.",
        SettingsField.MySqlConnectionsProfile => "Enter opens the profile's `mysql.json` in your editor (created with commented examples).",
        SettingsField.MySqlConnectionsGlobal => "Enter opens the home folder's `mysql.json`, which every profile reads, in your editor. The profile's wins on a name clash.",
        SettingsField.UncTools => "Offers the UNC tools over the shares in `unc.json`, once one is defined: `unc_shares`, `unc_search`, `unc_info`, `unc_read`, and `unc_fetch` while the File tools are on. See UNC shares. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *UNC shares offered*.",
        SettingsField.UncWrites => "The master key of every change on a share. Off, every share is read-only. On, a share whose `access` is `readwrite` also gets `unc_write`, `unc_patch`, `unc_create_directory`, `unc_move`, `unc_copy`, `unc_delete` (off by default in the Offered tab) and `unc_put`. Changes there are permanent.",
        SettingsField.UncSharesOffered => "A checklist of the shares in both `unc.json` files, as *SQL connections offered* is for `sql.json`: nothing until ticked.",
        SettingsField.UncDefaultShare => "The share used when a call names none and gives no full path: one of the offered shares, or the first.",
        SettingsField.UncSetPassword => "Pick a runas share and type its password, masked. It is saved to that share's store: encrypted in its `unc.json`, or in Windows Credential Manager.",
        SettingsField.UncAddShare => "A wizard for a new share, or to edit a saved one (as SQL add/edit connection does). It can **test** the draft before saving it by listing its root under its account.",
        SettingsField.UncStarMention => "Typing `*` and part of a name on the input line lists the offered shares (path, read-write, description); a pick writes `*name` as text. The database connections keep `%`.",
        SettingsField.UncSharesProfile => "Enter opens the profile's `unc.json` in your editor (created with commented examples).",
        SettingsField.UncSharesGlobal => "Enter opens the home folder's `unc.json`, which every profile reads, in your editor. The profile's wins on a name clash.",
        SettingsField.EmbeddedVramOnly => "Keeps the embedded model in the GPU's memory. Every layer goes on the GPU (whatever *Embedded GPU layers* says; with *Embedded context size* 0 the context shrinks to fit instead). If the model still ends up partly in system RAM, the app stops the server and the connect fails with what to lower. That covers layers left on the CPU, a buffer that could not be allocated, and memory the NVIDIA driver quietly moved to shared GPU memory. Refused on the CPU backend, on Vulkan with an integrated GPU (one with under 1 GiB of its own memory), and when llama-server does not report where it put the layers, so the load cannot be checked. The driver can also be told never to do that for llama.cpp: in the NVIDIA Control Panel, *Manage 3D settings* › *Program Settings*, add `llama-server.exe` (under `llama\\` in the home folder) and set *CUDA - Sysmem Fallback Policy* to *Prefer No Sysmem Fallback*. A profile saved while the default was off keeps it off.",
        SettingsField.MenuMaxHeight => "The most of the window a menu or info pane (`/settings`, `/tools`, `/skills`, `/mcp`, `/help`, `/usage`, `/cwd browse`…) may take, its rules and hint row included: `half-screen`, `three-quarters` or `full-screen` (all but one row). A longer list scrolls inside it. Every tab of a pane keeps the height of its tallest tab, so the pane does not jump as you tab through it.",
        SettingsField.ProjectFile => "Reads `NEON.md` (or `AGENTS.md`) in the working directory into the prompt as project notes. When off, those files are ignored. Like the skills, it needs Agent skills on.",
        SettingsField.ImageEditQuality => "The quality `image_edit` writes a JPEG (or JPEG XL, HEIF) at when the model gives none (1–100), and where `max_kb` starts lowering it from.",
        SettingsField.ImageEditMetadata => "The metadata `image_edit` keeps unless the model asks otherwise: `none` drops it all (no camera, date or place), `basic` keeps author, copyright, title, comment, date taken, camera and exposure, `all` also keeps the GPS position, so the picture says where it was taken.",
        SettingsField.ImageEditMode => "Where an edited picture goes: `beside-original` writes a new file beside the source (`photo-edited.png`; `image_edit` uses *Image edit output folder* when it is set), `overwrite-original` replaces the source (a format change writes `photo.jpg` and deletes `photo.png`). It rules the picture windows' right-click menu (`/view`, `/view --thumbs`) and `image_edit` when the model names no `to`. No confirmation either way.",
        SettingsField.ImageEditOutputFolder => "Where `image_edit` writes when the model names no `to`: a folder under the working directory, made on first use. Empty writes beside the source picture.",
        SettingsField.FileSearchMaxResults => "The most rows one `search_files` or `unc_search` call returns, whatever its `limit` asks (1–5000): hits, listed entries, matching names or recent files. A call without `limit` still gets 50 hits, 200 entries, 100 names or 10 recent files.",
        SettingsField.WebDownloadMaxMegabytes => "The largest file `download_file` saves (1–102400). The file streams to disk, so a big cap costs disk space, not memory. A download that sends nothing for 60 seconds is dropped, and a partial file never stays.",
        SettingsField.QueryResultMaxChars => "The most characters of table one `sql_query`, `oracle_query` or `mysql_query` answer carries (1000–1000000); the rows past it are left off and the header says how many fit. One setting for all three engines.",
        SettingsField.ReflectionInstalledSkills => "What a reflection may do to a skill installed with `/skills add`. `read-only` refuses any change and asks it to write a companion skill instead, so a later update from the same source stays clean. `allow-and-mark` lets it change the skill; an update from its source then warns first, and the skill's revert on `/skills` can bring the earlier version back.",
        SettingsField.DockerTools => "Offers the Docker tools: `docker_containers`, `docker_logs`, `docker_inspect`, `docker_stats`, `docker_resources` and `docker_compose`. They are offered whether Docker Desktop runs or not (they say when it does not). `/docker` works either way. See Docker.",
        SettingsField.DockerWrites => "The master key of the model's changes. Off, the model may only look. On, it also gets `docker_lifecycle`, `docker_pull`, `docker_remove` and `docker_prune` (the last two off by default in the Offered tab), and every one of those calls waits for your yes on the pane. Headless refuses them.",
        SettingsField.DockerEnginePipe => "The Docker engine's named pipe: `docker_engine` (Docker Desktop's), any other name, `\\\\.\\pipe\\name` or the CLI's `npipe:////./pipe/name`. Blank is the default.",
        SettingsField.DockerServers => "Offers the chosen containers in `/server`. Turning it off while one is in use stops it at the reconnect.",
        SettingsField.DockerServerContainers => "Which containers are servers: a checklist of every container the engine lists, with its state, image and ports (Enter or Space ticks one; select all or none). A ticked name the engine no longer lists is dropped when the checklist opens, and the status line names it.",
        SettingsField.DockerServerStopTimeoutSeconds => "How long a stopping container gets before the engine kills it (0–120).",
        SettingsField.DockerServerPostStopDelaySeconds => "The wait between the stops and the start, so the GPU's memory is free (0–60).",
        SettingsField.DockerServerReadyTimeoutSeconds => "How long a started container may take to answer on `/v1/models` (30–3600). Past it the switch fails and the container is left running.",
        SettingsField.DockerServerStopOnExit => "Stops the container in use when the app exits, the window's close button included. Off, it keeps running.",
        SettingsField.SttDestination => "Where what you say goes. `chat`: sent to the model straight away. `draft`: added to the end of the input line (after a space if needed) for you to edit and send with Enter; push-to-talk and the wake word then work with text on the line too (except a push-to-talk key of `Home`, `End`, `PageUp` or `PageDown`, which still move around the draft). Applies to an interruption's request as well.",
        SettingsField.CameraTools => "Offers `camera_capture`, which lets the model ask you for a photo. Never offered without the pane, headless, or to an embedded model without vision. `/camera` works either way. The top of its on/off page (`/tools camera`, the toolbar's 📸) has a **watch** button (W) that starts or stops `/camera watch`, **live** (L) that opens or closes the camera's window, and **snap** (S) and **screen** (C), which close the pane and run `/camera snap` or `/screen`.",
        SettingsField.CameraShutter => "Who takes the model's photo. `user`: the camera pane shows the model's request; Space takes the photo, R takes it again, Enter sends it, ESC declines. `model`: a pane asks Deny / Allow once / Allow for this session (cleared by `/new`, `/clear` and a profile switch), and on a yes the app takes the photo at once.",
        SettingsField.CameraPreview => "`live`: a camera window of its own (beside the picture viewer, never in its place) shows the camera live (mirrored) while you frame the shot, then holds the photo taken. `post`: the viewer opens on the photo once it is taken. `disabled`: no window. The viewer never takes the keyboard from the terminal.",
        SettingsField.CameraDevice => "The camera, by the name Windows lists it under, picked from the ones connected. `(first camera)` uses the first; a camera that is not connected uses the first, with a notice.",
        SettingsField.CameraResolution => "The size the camera is asked for (`640x480`, `1280x720` or `1920x1080`). The camera runs at its own size nearest it, and a photo is scaled to fit the longer side.",
        SettingsField.CameraKeepInSessions => "Off: a stored session keeps a line naming the photo instead of the picture (the file stays in the *Camera output folder*), so a resumed session does not carry your face. On: photos are stored like any picture.",
        SettingsField.CameraWatchSeconds => "How often `/camera watch` looks (2–3600).",
        SettingsField.CameraWatchThreshold => "How much of the picture must change for watch mode to keep a frame (1–100). Shifts in brightness do not count. `--camera-check` prints your camera's own noise.",
        SettingsField.CameraWatchUnprompted => "Off: a changed picture rides your next message. On: the model is shown it unasked, no more often than *Camera watch min gap (s)*, and only while no reply runs, nothing speaks and the input line is empty.",
        SettingsField.CameraWatchMinGapSeconds => "The least time between two unprompted watch turns (30–3600).",
        SettingsField.BotChatCamera => "The bots see you: the camera stays on for the chat, and each bot's turn gets a fresh picture from it, last after the chat's own pictures (4 in all), captioned as a photo of you (User, as the chat names you) and not from any bot; the bots' instructions say the same. The pictures are kept in memory only, never saved. Only for models that read images; a camera that fails is one warning and the chat goes on without it. Read when a chat starts.",
        SettingsField.PostgresTools => "Offers the nine PostgreSQL tools (connections, databases, schemas, tables, columns, describe, relationships, indexes, query) over the connections of postgres.json this profile offers. They only read: the session starts read-only with a statement timeout, and every statement runs in a read-only transaction that is rolled back. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *PostgreSQL connections offered*.",
        SettingsField.PostgresMode => "`read-only`: the PostgreSQL tools only read. `read-write`: `postgres_execute` is offered too, on the connections whose entry in postgres.json says `\"access\": \"readwrite\"` (the default is `read`; the wizard asks) — one statement per call of the kinds *PostgreSQL statements allowed* ticks (changing data, creating and reading by default), committed as it runs. Each change asks first: Deny, Allow once, or Allow for this session (that connection and database, until the session ends); a read asks nothing and runs read-only. BEGIN/COMMIT, SET, GRANT/REVOKE, COPY, LOCK, PREPARE/EXECUTE and CREATE or DROP of a database, role, extension or server stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.PostgresStatementsAllowed => "Under *PostgreSQL mode* `read-write`: the kinds of statement `postgres_execute` may run, ticked on a checklist — changing data (INSERT, UPDATE, MERGE), deleting (DELETE, TRUNCATE), creating (CREATE TABLE, INDEX, VIEW, SEQUENCE, TYPE, SCHEMA…), changing structure (ALTER …, COMMENT ON), dropping (DROP …), upkeep (VACUUM, ANALYZE, REINDEX, CLUSTER, REFRESH MATERIALIZED VIEW), procedures and triggers (CALL, DO, and making a function, procedure, trigger or rule, whose code runs later) and reading (SELECT). A statement needs the kind of every change in it (a WITH that deletes needs deleting). A / N / D pick all, none or the default (changing data, creating, reading). With none ticked, `postgres_execute` is not offered.",
        SettingsField.PostgresConnectionsOffered => "Which connections of postgres.json (the profile's and the global one) this profile offers to the model. None are offered until you tick them. A ticked name no longer in the files is dropped when the checklist opens, as on *SQL connections offered*.",
        SettingsField.PostgresDefaultConnection => "The connection a PostgreSQL tool uses when the model names none; `(the first connection)` uses the first offered.",
        SettingsField.PostgresSetPassword => "Pick a connection and type its password (masked); it is saved encrypted in postgres.json or in Windows Credential Manager, as the connection says.",
        SettingsField.PostgresAddConnection => "A wizard for a new connection, or to edit a saved one (as SQL add/edit connection does): which postgres.json, the name, host, port, database, user, where the password is kept, the password, TLS, the connect timeout, the access and a description; its test shows who it signs in as and warns when the role could change data (a superuser is warned of, not refused).",
        SettingsField.PostgresPercentMention => "On: `%` and part of a name on the input line lists the PostgreSQL connections too, marked `PostgreSQL ·`.",
        SettingsField.PostgresQueryMaxRows => "The rows a `postgres_query` returns when the model does not say (1–100,000); the header says when more exist.",
        SettingsField.PostgresQueryTimeoutSeconds => "Seconds one statement may run (1–600): the server's own statement_timeout.",
        SettingsField.PostgresConnectionsProfile => "Opens this profile's postgres.json in your editor (made with commented examples when missing). The tools read it at their next call.",
        SettingsField.PostgresConnectionsGlobal => "Opens the global postgres.json, every profile's, in your editor. A name in both is this profile's.",
        SettingsField.SqliteTools => "Offers the four SQLite tools (`sqlite_databases`, `sqlite_tables`, `sqlite_describe`, `sqlite_query`) over the databases of sqlite.json this profile offers, and the working directory's files under *SQLite sandbox files*. Those four only read: the file is opened read-only, `query_only` is set, and every statement runs in a transaction that is rolled back. *SQLite mode* `read-write` adds a fifth, `sqlite_execute`, that may change a database. The top of its on/off page (the toolbar's item) has an **offered** button (O) that shows how many are offered and opens *SQLite databases offered*. While on, the shell police refuses a command or script that reaches SQLite (under *Shell police*), and the file tools never change a database file (`.db`, `.db3`, `.sqlite`, `.sqlite3`, or one sqlite.json names): a database changes only through `sqlite_execute`.",
        SettingsField.SqliteMode => "`read-only`: the SQLite tools only read. `read-write`: `sqlite_execute` is offered too — one statement per call of the kinds *SQLite statements allowed* ticks (changing data, creating and reading by default), committed as it runs, and with `create` (creating ticked) a new database file (.db, .sqlite, .sqlite3, .db3) in the working directory under *SQLite sandbox files*. Each change asks first: Deny, Allow once, or Allow for this session (that file, until the session ends); a read (SELECT, VALUES, EXPLAIN) asks nothing and runs on the file opened read-only. ATTACH, DETACH, BEGIN/COMMIT, VACUUM INTO, `writable_schema`, `sqlite_dbpage` and `load_extension` stay refused. Never offered headless or in plan mode; every change is written to the log.",
        SettingsField.SqliteStatementsAllowed => "Under *SQLite mode* `read-write`: the kinds of statement `sqlite_execute` may run, ticked on a checklist — changing data (INSERT, UPDATE, REPLACE), deleting (DELETE), creating (CREATE TABLE, INDEX, VIEW, TRIGGER, VIRTUAL TABLE), changing structure (ALTER TABLE), dropping (DROP …), upkeep (VACUUM, REINDEX, ANALYZE), settings (PRAGMA) and reading (SELECT, VALUES, EXPLAIN). A `WITH` counts as the statement after it. `create` needs creating. A / N / D pick all, none or the default (changing data, creating, reading). With none ticked, `sqlite_execute` is not offered.",
        SettingsField.SqliteDatabasesOffered => "Which databases of sqlite.json (the profile's and the global one) this profile offers to the model. None are offered until you tick them. A ticked name no longer in the files is dropped when the checklist opens, as on *SQL connections offered*.",
        SettingsField.SqliteDefaultDatabase => "The database a SQLite tool uses when the model names none; `(the first database)` uses the first offered.",
        SettingsField.SqliteSandboxFiles => "On: the model may also open any SQLite file inside the working directory by its path (`data/app.db`); a path outside it is refused, as for the file tools.",
        SettingsField.SqliteAddDatabase => "A wizard for a new database, or to edit a saved one (as SQL add/edit connection does): which sqlite.json (this profile's or the global one), the name, the database file and a description, then a test that opens it read-only, and Save (offered, or hidden until ticked).",
        SettingsField.SqlitePercentMention => "On: `%` and part of a name on the input line lists the SQLite databases too, beside the other database connections.",
        SettingsField.SqliteQueryMaxRows => "The rows a `sqlite_query` returns when the model does not say (1–100,000); the header says when more exist.",
        SettingsField.SqliteQueryTimeoutSeconds => "Seconds a SQLite statement may run before it is interrupted (1–600).",
        SettingsField.SqliteDatabasesProfile => "Opens this profile's sqlite.json in your editor (made with a commented example when missing). The tools read it at their next call.",
        SettingsField.SqliteDatabasesGlobal => "Opens the global sqlite.json, every profile's, in your editor. A name in both is this profile's.",
        SettingsField.ScreenTools => "Offers `screen_capture` and `screen_list`, which let the model see a monitor, every monitor or one window. Never offered without the pane, headless, or to an embedded model without its vision projector. `/screen` works either way.",
        SettingsField.ScreenAsk => "`ask`: a pane names what would be captured and the model's reason; Deny, Allow once, or Allow for this session (remembered until the session ends). `allow`: taken without asking; the preview still shows what was sent.",
        SettingsField.ScreenPreview => "Opens the picture viewer on each screenshot taken (without taking the keyboard), so you see exactly what was sent.",
        SettingsField.ScreenOutputFolder => "The folder under the working directory the screenshots are saved in, made on first use. Empty means the working directory itself.",
        SettingsField.ScreenKeepInSessions => "Off: a stored session keeps a line naming the screenshot instead of the picture (the file stays in the *Screen capture output folder*), since a screenshot can hold anything that was on the screen. On: stored like any picture.",
        SettingsField.CameraOutputFolder => "The folder under the working directory the photos are saved in, made on first use. Empty means the working directory itself; it may be any folder under it, even the ComfyUI output folder. Watch mode's double-clicked pictures go in its `.watch` subfolder.",
        _ => "",
    };
}
